var n=`0686-fonio-with-vegetables`;var t=`world-0686`;var s=`GN`;var o=`western-africa`;var a=4;var r=35;var l={en:`Fonio with Vegetables`,ua:`Фоніо з овочами`};var g={en:`Fonio with Vegetables is a Guinea classic prepared with fonio, yellow onion, carrot, zucchini. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Фоніо з овочами, страва кухні країни Гвінея зі складниками: фоніо, жовта цибуля, морква, цукіні. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Cook the listed ingredients in simmering water for about 18 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 18 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:18,i:[[`fonio`,330,`g`],[`water`,600,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,190,`g`],[`carrot`,220,`g`],[`zucchini`,250,`g`],[`sunflower-oil`,45,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:5,i:[[`tomato`,240,`g`],[`parsley`,18,`g`],[`lemon-juice`,25,`ml`]]}];var d={slug:n,id:t,country:`GN`,region:o,servings:4,minutes:35,title:l,text:g,steps:u};export{s as country,d as default,t as id,r as minutes,o as region,a as servings,n as slug,u as steps,g as text,l as title};